def _eval_having(
    node: tuple,
    source_columns: tuple[tuple, ...],
    rows: tuple[int, ...],
    agg_values: tuple,
    group_index_set: set[int],
) -> bool | None:
    """Three-valued evaluation of a bound HAVING condition for one group."""
    tag = node[0]
    if tag == "literal":
        return node[1]
    if tag == "column":
        # Bound HAVING columns are always grouping columns; groups are never
        # empty (and the global aggregate case carries no column nodes).
        return source_columns[node[2]][rows[0]]
    if tag == "hagg":
        return agg_values[node[1]]
    if tag == "isnull":
        value = _eval_having(
            node[1], source_columns, rows, agg_values, group_index_set
        )
        result = value is None
        return (not result) if node[2] else result
    if tag == "not":
        value = _eval_having(
            node[1], source_columns, rows, agg_values, group_index_set
        )
        return None if value is None else (not value)
    if tag in ("and", "or"):
        # Short-circuit SQL semantics; UNKNOWN propagates only when needed.
        left = _eval_having(
            node[1], source_columns, rows, agg_values, group_index_set
        )
        right = _eval_having(
            node[2], source_columns, rows, agg_values, group_index_set
        )
        if tag == "and":
            if left is False or right is False:
                return False
            if left is None or right is None:
                return None
            return True
        if left is True or right is True:
            return True
        if left is None or right is None:
            return None
        return False
    if tag == "cmp":
        left = _eval_having(
            node[2], source_columns, rows, agg_values, group_index_set
        )
        right = _eval_having(
            node[3], source_columns, rows, agg_values, group_index_set
        )
        if left is None or right is None:
            return None
        op = node[1]
        if op == "=":
            result = left == right
        elif op == "!=":
            result = left != right
        elif op == "<":
            result = left < right
        elif op == "<=":
            result = left <= right
        elif op == ">":
            result = left > right
        else:  # ">="
            result = left >= right
        return bool(result)
    raise QuerySyntaxError(f"unsupported expression: {tag}")  # pragma: no cover

