            _aggregate_value(
                agg.func, agg.arg_index, agg.arg_type, rows, source_columns
            )
            for agg in all_aggs
        )
        if having is not None and (
            _eval_having(having, source_columns, rows, agg_values, group_index_set)
            is not True
        ):
            continue
        values = []
        for item in bound_items:
            if item.kind == "column":
                values.append(source_columns[item.col_index][rows[0]])
            else:
                values.append(agg_values[proj_agg_slot[id(item)]])
        materialised.append(tuple(values))

